/* ------------------------------------------------------------------ *
 * Search helpers
 * ------------------------------------------------------------------ */

/** Maps a requested ingredient to the market specialty that carries it. */
const SPECIALTY_RULES: { match: string[]; specialty: string }[] = [
  {
    specialty: "মাছ",
    match: ["মাছ", "ইলিশ", "রুই", "চিংড়ি", "fish", "shrimp", "hilsa"],
  },
  {
    specialty: "মাংস",
    match: ["মাংস", "গরু", "খাসি", "মুরগি", "ডিম", "meat", "chicken", "beef", "mutton", "egg"],
  },
  {
    specialty: "সবজি",
    match: [
      "আলু", "পেঁয়াজ", "মরিচ", "টমেটো", "রসুন", "আদা", "শাক", "সবজি", "লাউ", "বেগুন",
      "গাজর", "potato", "onion", "chili", "chilli", "tomato", "garlic", "ginger", "vegetable",
    ],
  },
];

export function specialtyForIngredient(ingredient: string): string {
  const q = ingredient.trim().toLowerCase();
  for (const rule of SPECIALTY_RULES) {
    if (rule.match.some((m) => q.includes(m.toLowerCase()))) return rule.specialty;
  }
  // Rice, oil, spices, packaged goods → grocery shop / supermarket.
  return "দোকান";
}

/** Specialties needed to cover every requested ingredient. */
export function requiredSpecialties(ingredients: string[]): string[] {
  return [...new Set(ingredients.map(specialtyForIngredient))];
}

/** Great-circle distance in km. */
export function distanceKm(
  lat1: number,
  lng1: number,
  lat2: number,
  lng2: number,
): number {
  const R = 6371;
  const toRad = (d: number) => (d * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(a));
}

const toMinutes = (hhmm: string) => {
  const [h = "0", m = "0"] = hhmm.split(":");
  return Number(h) * 60 + Number(m);
};

/** Is the market open at the given local time (minutes since midnight)? */
export function isOpenAt(market: Market, minutesOfDay: number): boolean {
  const open = toMinutes(market.opens);
  const close = toMinutes(market.closes);
  return close > open
    ? minutesOfDay >= open && minutesOfDay < close
    : minutesOfDay >= open || minutesOfDay < close; // wraps past midnight
}

export function priceTier(index: number): "সাশ্রয়ী" | "মধ্যম" | "প্রিমিয়াম" {
  if (index <= 0.9) return "সাশ্রয়ী";
  if (index <= 1.1) return "মধ্যম";
  return "প্রিমিয়াম";
}

/* --------------------------- weekly cache --------------------------- */

const CACHE_KEY = "nearby-markets-cache-v2";
const WEEK_MS = 7 * 24 * 60 * 60 * 1000;

type CacheEntry = { at: number; markets: RankedMarket[] };

function cacheKey(lat: number, lng: number, ingredients: string[], maxDistance: number) {
  return [lat.toFixed(2), lng.toFixed(2), maxDistance, [...ingredients].sort().join("|")].join("::");
}

function readCache(key: string): RankedMarket[] | null {
  if (typeof localStorage === "undefined") return null;
  try {
    const all = JSON.parse(localStorage.getItem(CACHE_KEY) ?? "{}") as Record<string, CacheEntry>;
    const hit = all[key];
    if (!hit || Date.now() - hit.at > WEEK_MS) return null;
    return hit.markets;
  } catch {
    return null;
  }
}

function writeCache(key: string, markets: RankedMarket[]) {
  if (typeof localStorage === "undefined") return;
  try {
    const all = JSON.parse(localStorage.getItem(CACHE_KEY) ?? "{}") as Record<string, CacheEntry>;
    for (const [k, v] of Object.entries(all)) {
      if (Date.now() - v.at > WEEK_MS) delete all[k];
    }
    all[key] = { at: Date.now(), markets };
    localStorage.setItem(CACHE_KEY, JSON.stringify(all));
  } catch {
    /* storage full or unavailable — cache is best-effort */
  }
}

/* ----------------------- Google Maps (primary source) ---------------- */

import { findMarketsNearby, type PlaceResult } from "./markets.functions";

const PRICE_INDEX: Record<string, number> = {
  PRICE_LEVEL_INEXPENSIVE: 0.8,
  PRICE_LEVEL_MODERATE: 1.0,
  PRICE_LEVEL_EXPENSIVE: 1.25,
  PRICE_LEVEL_VERY_EXPENSIVE: 1.4,
};

function specialtiesForTypes(types: string[], name: string): string[] {
  const out = new Set<string>();
  if (types.includes("supermarket")) out.add("সুপারমার্কেট");
  if (types.includes("butcher_shop") || /meat|মাংস/i.test(name)) out.add("মাংস");
  if (types.includes("seafood_market") || /fish|মাছ/i.test(name)) out.add("মাছ");
  if (
    types.includes("market") ||
    /bazar|bazaar|বাজার|সবজি|vegetable/i.test(name)
  ) {
    out.add("সবজি");
    out.add("মাছ");
    out.add("মাংস");
  }
  if (
    types.includes("grocery_store") ||
    types.includes("food_store") ||
    types.includes("convenience_store") ||
    out.size === 0
  ) {
    out.add("দোকান");
  }
  return [...out];
}

function placeToRanked(p: PlaceResult, userLat: number, userLng: number): RankedMarket {
  return {
    id: p.id,
    name: p.name,
    city: "",
    country: "",
    lat: p.lat,
    lng: p.lng,
    address: p.address,
    phone: p.phone,
    opens: "",
    closes: "",
    avg_price_index: PRICE_INDEX[p.priceLevel ?? ""] ?? 1,
    rating: p.rating,
    reviews: p.reviews,
    specialties: specialtiesForTypes(p.types, p.name),
    distanceKm: distanceKm(userLat, userLng, p.lat, p.lng),
    openNow: p.openNow ?? true,
  };
}

/* --------------------------- main query ----------------------------- */

/**
 * Markets around the user's real position, from Google Maps.
 *
 * Ranking is distance-first on purpose: the closest shop must always be at
 * the top, whatever its size or price. Price and rating only break ties.
 * The bundled directory is a last-resort fallback when Maps is unreachable.
 */
export async function findNearbyMarkets(
  userLat: number,
  userLng: number,
  ingredients: string[],
  maxDistance: number = 5,
): Promise<RankedMarket[]> {
  const key = cacheKey(userLat, userLng, ingredients, maxDistance);
  const cached = readCache(key);
  // Never trust an empty cached result — that would keep an outage sticky.
  if (cached && cached.length > 0) return cached;

  const needed = requiredSpecialties(ingredients);
  const sort = (list: RankedMarket[]) =>
    [...list].sort(
      (a, b) =>
        a.distanceKm - b.distanceKm ||
        a.avg_price_index - b.avg_price_index ||
        b.rating - a.rating,
    );

  let ranked: RankedMarket[] = [];

  try {
    const res = await findMarketsNearby({
      data: { lat: userLat, lng: userLng, radiusKm: Math.min(maxDistance, 15) },
    });
    const all = res.places.map((p) => placeToRanked(p, userLat, userLng));
    const matching = all.filter(
      (m) => needed.length === 0 || needed.some((s) => m.specialties.includes(s)),
    );
    ranked = sort(matching.length > 0 ? matching : all).slice(0, 12);
  } catch (err) {
    console.error("Google Maps market search failed, using offline directory", err);
  }

  if (ranked.length === 0) {
    // Offline fallback: the bundled directory, still closest-first. Only ever
    // show entries that are genuinely near the user — never a far-away city.
    const FALLBACK_MAX_KM = 25;
    const now = new Date();
    const minutes = now.getHours() * 60 + now.getMinutes();
    const all = MARKETS.map((m) => ({
      ...m,
      distanceKm: distanceKm(userLat, userLng, m.lat, m.lng),
      openNow: isOpenAt(m, minutes),
    })).filter((m) => m.distanceKm <= FALLBACK_MAX_KM);
    ranked = sort(
      all.filter(
        (m) => needed.length === 0 || needed.some((s) => m.specialties.includes(s)),
      ),
    ).slice(0, 12);
  }

  if (ranked.length > 0) {
    const cheapest = [...ranked].sort(
      (a, b) => a.avg_price_index - b.avg_price_index || a.distanceKm - b.distanceKm,
    )[0];
    if (cheapest) cheapest.cheapest = true;
  }

  if (ranked.length > 0) writeCache(key, ranked);
  return ranked;
}

